using System;using System.Collections.Generic;using System.Linq;using UnityEngine;using UnityEditor;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckMattressRacing.Editor {
public static class MattressPillowAuthoring {
 const string Path="Assets/TruckMattressRacing/Materials/Actual loose bed pillow.asset";
 public static void Install(MattressMatch m){if(m.world==null||m.world.pillows!=null&&m.world.pillows.Length==16)return;var root=m.world.transform;var mesh=PillowMesh();var cloth=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckMattressRacing/Materials/Actual patterned Bed fabric.mat");if(cloth==null)throw new Exception("Existing real Bed fabric missing");var contact=SportsEventAuthoring.Contact(MattressAuthoring.Folder,"Loose pillow cloth",.28f,.15f);m.world.pillows=new Rigidbody[16];
  for(int i=0;i<16;i++){var g=new GameObject("Loose player pillow "+i);g.transform.SetParent(root,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=cloth;var c=g.AddComponent<MeshCollider>();c.sharedMesh=mesh;c.convex=true;c.sharedMaterial=contact;var b=g.AddComponent<Rigidbody>();b.mass=.28f;b.linearDamping=.08f;b.angularDamping=.4f;b.maxLinearVelocity=40;b.maxAngularVelocity=16;b.interpolation=RigidbodyInterpolation.Interpolate;b.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;b.isKinematic=true;m.world.pillows[i]=b;}
  m.world.ResetPillows();
  // Only the world ghost changes. Keep the existing eight vehicle ghosts and recorder configuration.
  var old=m.replay.ghosts[8];UnityEngine.Object.DestroyImmediate(old.gameObject);var ghost=UnityEngine.Object.Instantiate(root.gameObject);ghost.name="Recorded render-only 8";ghost.transform.SetParent(null);foreach(var joint in ghost.GetComponentsInChildren<Joint>(true))UnityEngine.Object.DestroyImmediate(joint);foreach(var t in ghost.GetComponentsInChildren<Transform>(true)){t.gameObject.layer=0;foreach(var c in t.GetComponents<Component>())if(!(c is Transform)&&!(c is Renderer)&&!(c is MeshFilter))UnityEngine.Object.DestroyImmediate(c);}m.replay.ghosts[8]=ghost.transform;ghost.SetActive(false);m.world.Freeze();EditorUtility.SetDirty(m.world);EditorUtility.SetDirty(m.replay);
 }
 static Mesh PillowMesh(){var existing=AssetDatabase.LoadAssetAtPath<Mesh>(Path);if(existing!=null)return existing;var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/HQ_ResidentialHouse/Objects/Bed.FBX").GetComponentsInChildren<MeshFilter>(true).OrderByDescending(f=>f.sharedMesh.vertexCount).First().sharedMesh;var v=source.vertices;var triangles=source.triangles;var parent=Enumerable.Range(0,v.Length).ToArray();Func<int,int> find=null;find=i=>parent[i]==i?i:parent[i]=find(parent[i]);Action<int,int> join=(a,b)=>{a=find(a);b=find(b);if(a!=b)parent[b]=a;};var weld=new Dictionary<Vector3Int,int>();for(int i=0;i<v.Length;i++){var key=new Vector3Int(Mathf.RoundToInt(v[i].x*100000),Mathf.RoundToInt(v[i].y*100000),Mathf.RoundToInt(v[i].z*100000));if(weld.TryGetValue(key,out int j))join(i,j);else weld[key]=i;}for(int i=0;i<triangles.Length;i+=3){join(triangles[i],triangles[i+1]);join(triangles[i],triangles[i+2]);}
  var pillow=Enumerable.Range(0,v.Length).GroupBy(i=>find(i)).Select(g=>{var bounds=new Bounds(v[g.First()],Vector3.zero);foreach(int i in g)bounds.Encapsulate(v[i]);return new{id=g.Key,bounds,count=g.Count()};}).Where(g=>g.count>200&&g.bounds.size.x>.4f&&g.bounds.size.x<.8f&&g.bounds.size.z>.25f&&g.bounds.size.z<.6f&&g.bounds.size.y>.2f&&g.bounds.size.y<.5f).OrderBy(g=>g.id).First();var vertices=new List<Vector3>();var uv=new List<Vector2>();var indices=new List<int>();var map=new Dictionary<int,int>();var size=pillow.bounds.size;
  foreach(int index in triangles){if(find(index)!=pillow.id)continue;if(!map.TryGetValue(index,out int mapped)){mapped=vertices.Count;map[index]=mapped;var point=v[index]-pillow.bounds.center;vertices.Add(Vector3.Scale(point,new Vector3(.78f/size.x,.28f/size.y,.55f/size.z)));uv.Add(source.uv[index]);}indices.Add(mapped);}var mesh=new Mesh{name="Actual independent patterned bed pillow"};mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.SetTriangles(indices,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,Path);return mesh;
 }
}
}
